        // back shorter or longer with the pitch, exactly like the region does.
        const fi = Math.max(0, Math.min((entry.fadeIn || 0) / pitch, playDur));
        const fo = Math.max(0, Math.min((entry.fadeOut || 0) / pitch, playDur - fi));
