/* ---- libControl/SoundBrowser/gatherAll.js ---- */
(function(){
window.gatherAll = async (handle, prefix, files, names, builder, onEmit, depth) => {
    const AUDIO_RE = /\.(mp3|wav|wave|aif|aiff|aac|m4a|mp4|mov|mkv|webm|avi|m4v|3gp|flv|ogg|oga|flac|opus)$/i;
    const MAX_FILES = 4000;
    const NAME_MAX = 60000;
    if (depth > 12 || names.length >= NAME_MAX) return;
    const subdirs = [];
    for await (const [n, h] of handle.entries()) {
        if (names.length >= NAME_MAX) break;
        if (h.kind === 'directory') subdirs.push([n, h]);
        else if (AUDIO_RE.test(n)) {
            names.push({ name: n, sub: prefix });
            builder.add(n, prefix);
            if (files.length < MAX_FILES) files.push({ name: n, handle: h, sub: prefix });
            if (names.length % 250 === 0) onEmit();   // grow the chip list live
        }
    }
    for (const [n, h] of subdirs) { if (names.length >= NAME_MAX) break; await window.gatherAll(h, prefix ? `${prefix}/${n}` : n, files, names, builder, onEmit, depth + 1); }
};

})();

/* ---- libControl/SoundBrowser/gatherMatching.js ---- */
(function(){
window.gatherMatching = async (handle, prefix, out, term, depth) => {
    const AUDIO_RE = /\.(mp3|wav|wave|aif|aiff|aac|m4a|mp4|mov|mkv|webm|avi|m4v|3gp|flv|ogg|oga|flac|opus)$/i;
    const DEEP_MAX = 20000;
    if (depth > 12 || out.length >= DEEP_MAX) return;
    const subdirs = [];
    for await (const [n, h] of handle.entries()) {
        if (out.length >= DEEP_MAX) break;
        if (h.kind === 'directory') subdirs.push([n, h]);
        else if (AUDIO_RE.test(n) && n.toLowerCase().includes(term)) out.push({ name: n, handle: h, sub: prefix });
    }
    for (const [n, h] of subdirs) { if (out.length >= DEEP_MAX) break; await window.gatherMatching(h, prefix ? `${prefix}/${n}` : n, out, term, depth + 1); }
};

})();

/* ---- libControl/SoundBrowser/makeChipBuilder.js ---- */
(function(){
window.makeChipBuilder = () => {
    const map = new Map(); // lowerToken -> { display, count, folders:Set }
    return {
        add(name, sub) {
            const base = name.replace(/\.[^.]+$/, '');
            const parts = base.split(/[^A-Za-z0-9]+/).filter((t) => t.length >= 2 && !/^\d+$/.test(t));
            const seen = new Set();
            parts.forEach((p) => {
                const k = p.toLowerCase();
                if (seen.has(k)) return; seen.add(k);
                let e = map.get(k); if (!e) { e = { display: p, count: 0, folders: new Set() }; map.set(k, e); }
                e.count++; e.folders.add(sub || '');
            });
        },
        top() {
            return Array.from(map.values())
                .filter((e) => e.count >= 2)
                .sort((a, b) => (b.folders.size - a.folders.size) || (b.count - a.count))
                .slice(0, 28);
        },
    };
};

})();

