      ctx.lineWidth = 2;
      ctx.beginPath();
      const hz = scanData.musicality.pitchHz || 440;
      const normPitchY = midY - Math.log2(hz / 110) * 15;
      ctx.moveTo(0, normPitchY);
      ctx.lineTo(width, normPitchY);
      ctx.stroke();

      // Pitch label
      ctx.fillStyle = '#f4902c';
      ctx.font = '10px monospace';
